{
  "title": "4.Ahiret Hayatının Aşamaları",
  "htmlContent": "<!DOCTYPE html>
<html lang="tr">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Ahiret Yolculuğu: Ebedi Hayatın Aşamaları</title>
    <script src="https://cdn.tailwindcss.com"></script>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;900&display=swap" rel="stylesheet">
    <style>
        /* Palet: Deep Night Sky (Dark Blue/Violet) with Cyan/Green Accents */
        body {
            font-family: 'Inter', sans-serif;
            background-color: #121223; /* Deep Dark Violet */
        }
        .flow-card {
            background-color: #1D1D3A; /* Card Background */
            transition: all 0.4s cubic-bezier(0.25, 0.8, 0.25, 1);
            border-bottom: 5px solid #4CAF50; /* Green Accent Bottom Border */
            box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.3), 0 4px 6px -4px rgba(0, 0, 0, 0.2);
        }
        .flow-card:hover {
            transform: translateY(-5px);
            box-shadow: 0 15px 30px rgba(0, 0, 0, 0.6);
            border-bottom-color: #00BCD4; /* Cyan on hover */
        }
        .final-card {
             background-image: linear-gradient(135deg, #176B87, #053B50);
             box-shadow: 0 20px 40px rgba(0, 0, 0, 0.8);
        }
        .card-number {
            font-weight: 900;
            font-size: 1.5rem;
            background-color: #00BCD4; /* Cyan Accent */
            color: #121223;
            width: 40px;
            height: 40px;
            display: flex;
            align-items: center;
            justify-content: center;
            border-radius: 50%;
            flex-shrink: 0;
            box-shadow: 0 0 10px rgba(0, 188, 212, 0.5);
        }
        /* SIRALAMA ETKİNLİĞİ STİLLERİ */
        .sortable-item {
            background-color: #1D1D3A;
            border: 2px solid #4CAF50;
            cursor: grab; /* Sürükleme imleci */
            user-select: none; /* Metin seçimini engelle */
            transition: all 0.2s;
            transform: scale(1);
        }
        .sortable-item:nth-child(even) {
            background-color: #1a1a33;
        }
        .sortable-item:active {
            cursor: grabbing;
        }
        .sortable-item.dragging {
            opacity: 0.5;
            border-style: dashed;
            border-color: #00BCD4;
            transform: scale(1.01);
        }
        .nav-tab.active {
            background-color: #1D1D3A; 
            color: #00BCD4;
            border-bottom: 2px solid #00BCD4;
        }
        .nav-tab {
            background-color: #121223;
            color: #888;
        }
        .sort-number {
            color: #00BCD4; /* Cyan Accent */
            font-weight: 700;
            font-size: 1.5rem;
            width: 30px; /* Sabit genişlik */
            text-align: right;
        }
    </style>
</head>
<body class="text-gray-200">
    <div class="container mx-auto p-4 md:p-8">
        <header class="text-center mb-10 pt-8">
            <h1 class="text-5xl md:text-7xl font-extrabold text-[#00BCD4] mb-4 tracking-tight">Ebediyete Yolculuk</h1>
            <p class="text-xl md:text-2xl text-[#E0E0E0] italic">Ahiret Hayatının Yedi Ana Aşaması</p>
        </header>

        <main class="max-w-6xl mx-auto">
            <!-- Tab Navigasyonu (Sayfa Geçişi) -->
            <nav class="flex justify-center space-x-4 mb-10 border-b border-[#1D1D3A]">
                <button id="tab-infographic" onclick="switchView('infographic')" class="nav-tab py-2 px-6 rounded-t-lg font-bold transition duration-300 active">
                    1. Sayfa: Infografik
                </button>
                <button id="tab-sorting" onclick="switchView('sorting')" class="nav-tab py-2 px-6 rounded-t-lg font-bold transition duration-300">
                    2. Sayfa: Sıralama Etkinliği
                </button>
            </nav>

            <!-- 1. SAYFA: INFOGRAFİK -->
            <div id="infographic-view" class="view-content">
                <div class="text-center p-6 bg-[#1D1D3A] rounded-xl mb-12 shadow-lg border-b-4 border-[#4CAF50]">
                     <p class="text-lg text-gray-300">İmtihan amacıyla gönderildiğimiz bu kısa dünya hayatı gelip geçicidir. İslam inancına göre ölüm bir son değil, sonsuzluğa giden yolculuğun ilk adımıdır. Aşağıdaki aşamalar, bu manevi serüvenin temel duraklarını göstermektedir.</p>
                </div>

                <!-- Aşamalar (Grid Düzeni) -->
                <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 mb-12">

                    <!-- AŞAMA 1: ECEL VE ÖLÜM -->
                    <div id="olum" class="flow-card rounded-xl p-6 shadow-xl">
                        <div class="flex items-center mb-4">
                            <div class="card-number mr-3">1</div>
                            <div>
                                <h2 class="text-xl font-bold text-[#00BCD4]">Ecel ve Ölüm</h2>
                                <p class="text-sm text-gray-400">Dünya Hayatının Perdesi Kapanıyor</p>
                            </div>
                        </div>
                        <p class="text-md text-gray-300">Her canlının belirli bir ömrü vardır. Ölüm, ruhun bedenden ayrılmasıyla gerçekleşir ve ahiret hayatına atılan ilk adımdır. <span class="font-semibold italic">"Her nefis ölümü tadacaktır."</span></p>
                    </div>

                    <!-- AŞAMA 2: KABİR HAYATI -->
                    <div id="berzah" class="flow-card rounded-xl p-6 shadow-xl">
                        <div class="flex items-center mb-4">
                            <div class="card-number mr-3">2</div>
                            <div>
                                <h2 class="text-xl font-bold text-[#00BCD4]">Kabir Hayatı (Berzah)</h2>
                                <p class="text-sm text-gray-400">Ruhların Bekleyiş Durağı</p>
                            </div>
                        </div>
                        <p class="text-md text-gray-300">Ölümden sonra başlayıp yeniden dirilişe kadar süren ara bekleme dönemidir. Bu "engel" veya "perde" aleminde, ruhlar kıyameti bekler.</p>
                    </div>

                    <!-- AŞAMA 3: KIYAMET -->
                    <div id="kiyamet" class="flow-card rounded-xl p-6 shadow-xl">
                        <div class="flex items-center mb-4">
                            <div class="card-number mr-3">3</div>
                            <div>
                                <h2 class="text-xl font-bold text-[#00BCD4]">Kıyamet</h2>
                                <p class="text-sm text-gray-400">Evrenin ve Tüm Canlıların Sonu</p>
                            </div>
                        </div>
                        <p class="text-md text-gray-300">İsrafil (a.s.)'ın Sûr'a ilk kez üflemesiyle evrenin düzeni bozulur ve dünya hayatı tüm varlıklar için toplu olarak son bulur.</p>
                    </div>

                    <!-- AŞAMA 4: BA'S -->
                    <div id="bas" class="flow-card rounded-xl p-6 shadow-xl">
                        <div class="flex items-center mb-4">
                            <div class="card-number mr-3">4</div>
                            <div>
                                <h2 class="text-xl font-bold text-[#00BCD4]">Ba's (Yeniden Diriliş)</h2>
                                <p class="text-sm text-gray-400">İkinci Hayata Dönüş</p>
                            </div>
                        </div>
                        <p class="text-md text-gray-300">Sûr'a ikinci kez üflenmesiyle, ölen tüm insanlar ruh ve bedenleriyle birlikte yeniden hayata döndürülür. Hesap gününün başlangıcıdır.</p>
                    </div>

                    <!-- AŞAMA 5: HAŞR VE MAHŞER -->
                    <div id="hasr" class="flow-card rounded-xl p-6 shadow-xl">
                        <div class="flex items-center mb-4">
                            <div class="card-number mr-3">5</div>
                            <div>
                                <h2 class="text-xl font-bold text-[#00BCD4]">Haşr ve Mahşer</h2>
                                <p class="text-sm text-gray-400">Büyük Hesaplaşma Meydanı</p>
                            </div>
                        </div>
                        <p class="text-md text-gray-300"><span class="font-semibold">Haşr</span>, diriltilen insanların sorgulanmak üzere toplanma eylemidir. Bu toplanmanın gerçekleştiği geniş alana <span class="font-semibold">Mahşer</span> denir.</p>
                    </div>

                    <!-- AŞAMA 6: HESAP, MİZAN, SIRAT -->
                    <div id="hesap" class="flow-card rounded-xl p-6 shadow-xl">
                        <div class="flex items-center mb-4">
                            <div class="card-number mr-3">6</div>
                            <div>
                                <h2 class="text-xl font-bold text-[#00BCD4]">Hesap, Mizan ve Sırat</h2>
                                <p class="text-sm text-gray-400">Adaletin Tezahürü</p>
                            </div>
                        </div>
                        <p class="text-md text-gray-300">Amel defterleri verilir, <span class="font-semibold">Mizan</span> ile tartım yapılır ve sonrasında Cennet'e ulaşmak için cehennem üzerine kurulu <span class="font-semibold">Sırat</span> köprüsünden geçiş denemesi yapılır.</p>
                    </div>
                </div>

                <!-- AŞAMA 7: EBEDİ YURT (Full Width Final Card) -->
                <div id="sonuc" class="final-card w-full rounded-xl shadow-2xl p-6 md:p-8 mt-10 mb-20">
                    <h2 class="text-4xl font-extrabold text-center text-white mb-8 tracking-wide">7. Nihai Hedef: Sonsuz Yaşam (Cennet/Cehennem)</h2>
                    <div class="grid grid-cols-1 md:grid-cols-2 gap-6 text-white">
                        <div class="p-6 rounded-lg border-2 border-[#4CAF50] bg-[#4CAF50]/30 transition duration-300 hover:bg-[#4CAF50]/50">
                            <h3 class="text-3xl font-semibold mb-3 text-[#4CAF50]">Cennet (Mükâfat Yurdu) 🕌</h3>
                            <p class="text-gray-200">İman edip salih ameller işleyenlerin ebedî olarak kalacakları, içinden ırmaklar akan Adn cennetleridir. En büyük mükâfat, Allah'ın rızasına ulaşmaktır.</p>
                        </div>
                        <div class="p-6 rounded-lg border-2 border-red-400 bg-red-600/30 transition duration-300 hover:hover:bg-red-600/50">
                            <h3 class="text-3xl font-semibold mb-3 text-red-400">Cehennem (Azap Yurdu) 🔥</h3>
                            <p class="text-gray-200">İman etmeyen ve kötü işler yapanların davranışlarının karşılığını göreceği azap yurdudur. Kur'an'da çeşitli şekillerde tasvir edilmiştir.</p>
                        </div>
                    </div>
                </div>
            </div>

            <!-- 2. SAYFA: SIRALAMA ETKİNLİĞİ -->
            <section id="sorting-view" class="view-content hidden max-w-xl mx-auto py-12 px-4">
                <h2 class="text-4xl font-bold text-center text-[#00BCD4] mb-8">Aşamaları Sıralayın</h2>
                <p class="text-center text-gray-300 mb-6">Kartları tutun ve sürükleyerek Ahiret yolculuğunun doğru sırasını oluşturun.</p>

                <div id="sortable-list" class="space-y-3">
                    <!-- Sıralanacak öğeler buraya JS ile yüklenecek -->
                </div>

                <div class="flex flex-col space-y-4 mt-8">
                    <button onclick="checkOrder()" class="w-full bg-[#4CAF50] text-white font-bold py-3 px-4 rounded-xl shadow-lg hover:bg-green-700 transition duration-300">
                        Sıralamayı Kontrol Et
                    </button>
                    <button onclick="resetGame()" class="w-full bg-gray-600 text-white font-bold py-3 px-4 rounded-xl shadow-lg hover:bg-gray-700 transition duration-300">
                        Yeniden Başlat
                    </button>
                </div>

                <div id="feedback" class="text-center text-xl mt-6 font-semibold">
                    <!-- Geri bildirim buraya gelecek -->
                </div>
            </section>
            <!-- SIRALAMA ETKİNLİĞİ BÖLÜMÜ SONU -->

        </main>

        <footer class="text-center mt-16 py-6 border-t border-[#1D1D3A]">
            <p class="text-md text-[#00BCD4] italic">"Asıl hayat ahiret yurdundaki hayattır. Keşke bilseler!" (Ankebût, 64)</p>
            <p class="text-xs text-gray-500 mt-2">Bu infografik, Kur'an ve Sünnet'te geçen temel ahiret inancı aşamalarına göre düzenlenmiştir.</p>
        </footer>
    </div>

    <script>
        // Ahiret Yolculuğu Aşamaları (Doğru Sıra)
        const correctOrder = [
            { id: 'ecel', name: 'Ecel ve Ölüm' },
            { id: 'berzah', name: 'Kabir Hayatı (Berzah)' },
            { id: 'kiyamet', name: 'Kıyamet' },
            { id: 'bas', name: 'Ba\'s (Yeniden Diriliş)' },
            { id: 'hasr', name: 'Haşr ve Mahşer' },
            { id: 'hesap', name: 'Hesap, Mizan ve Sırat' },
            { id: 'ebedi', name: 'Ebedi Yurt (Cennet / Cehennem)' } // 7. ve son aşama eklendi
        ];

        const sortableList = document.getElementById('sortable-list');
        const feedbackElement = document.getElementById('feedback');
        let draggedItem = null;

        // Sayfa/Görünüm Değiştirme Fonksiyonu
        function switchView(viewId) {
            document.getElementById('infographic-view').classList.add('hidden');
            document.getElementById('sorting-view').classList.add('hidden');

            document.getElementById('tab-infographic').classList.remove('active');
            document.getElementById('tab-sorting').classList.remove('active');

            if (viewId === 'infographic') {
                document.getElementById('infographic-view').classList.remove('hidden');
                document.getElementById('tab-infographic').classList.add('active');
            } else {
                document.getElementById('sorting-view').classList.remove('hidden');
                document.getElementById('tab-sorting').classList.add('active');
                if (sortableList.children.length === 0) {
                     resetGame(); // Etkinlik görünür olduğunda yükle
                }
            }
        }

        // --- DRAG & DROP İŞLEMLERİ ---

        function handleDragStart(e) {
            draggedItem = this;
            e.dataTransfer.effectAllowed = 'move';
            e.dataTransfer.setData('text/html', this.innerHTML); 
            setTimeout(() => this.classList.add('dragging'), 0);
            feedbackElement.textContent = '';
            feedbackElement.className = 'text-center text-xl mt-6 font-semibold';
        }

        function handleDragEnd(e) {
            this.classList.remove('dragging');
            draggedItem = null;
            // Sürükleme bittiğinde numaraları tekrar kontrol et ve güncelle (sadece gerektiğinde)
            // Bu, handleDragOver içinde yapıldığı için burada sadece görsel temizlik yeterli.
        }

        function handleDragOver(e) {
            e.preventDefault(); 
            e.dataTransfer.dropEffect = 'move';
            const targetItem = e.target.closest('.sortable-item');
            if (targetItem && targetItem !== draggedItem) {
                // Sürüklenen öğeyi hedefin üstüne veya altına yerleştirme
                const rect = targetItem.getBoundingClientRect();
                const offsetY = e.clientY - rect.top;

                // Drop hedefinin hemen altında bir yer oluştur
                if (offsetY > rect.height / 2) {
                    sortableList.insertBefore(draggedItem, targetItem.nextSibling);
                } else {
                    sortableList.insertBefore(draggedItem, targetItem);
                }
                updateItemNumbers(); // DOM değiştiğinde numaraları güncelle
            }
        }

        function handleDrop(e) {
            e.stopPropagation(); // Bazı tarayıcılarda gereklidir
            return false;
        }

        // --- YARDIMCI FONKSİYONLAR ---

        // Sürükleme sonrası sıralama numaralarını günceller
        function updateItemNumbers() {
            const list = Array.from(sortableList.children);
            list.forEach((item, index) => {
                const numberElement = item.querySelector('.sort-number');
                if (numberElement) {
                    numberElement.textContent = (index + 1) + '.';
                }
            });
        }

        // Diziyi karıştırma fonksiyonu (Fisher-Yates)
        function shuffleArray(array) {
            let currentIndex = array.length, randomIndex;
            while (currentIndex !== 0) {
                randomIndex = Math.floor(Math.random() * currentIndex);
                currentIndex--;
                [array[currentIndex], array[randomIndex]] = [
                    array[randomIndex], array[currentIndex]
                ];
            }
            return array;
        }

        // Listeyi yeniden çizme fonksiyonu
        function renderList(stages) {
            sortableList.innerHTML = '';
            stages.forEach((stage) => {
                const itemDiv = document.createElement('div');
                itemDiv.dataset.id = stage.id;

                itemDiv.className = 'sortable-item flex items-center p-4 rounded-lg shadow-md hover:bg-[#1D1D3A]/80';
                itemDiv.setAttribute('draggable', 'true');

                // 1. Numara alanı oluşturma
                const numberSpan = document.createElement('span');
                numberSpan.className = 'sort-number mr-4 flex-shrink-0';

                // 2. Metin alanı oluşturma
                const nameSpan = document.createElement('span');
                nameSpan.textContent = stage.name;
                nameSpan.className = 'text-lg font-medium';

                itemDiv.appendChild(numberSpan);
                itemDiv.appendChild(nameSpan);

                // Drag and drop event listeners
                itemDiv.addEventListener('dragstart', handleDragStart);
                itemDiv.addEventListener('dragover', handleDragOver);
                itemDiv.addEventListener('drop', handleDrop);
                itemDiv.addEventListener('dragend', handleDragEnd);

                sortableList.appendChild(itemDiv);
            });
            updateItemNumbers(); // İlk numaralandırmayı yap
        }

        // Sıralamayı kontrol etme mantığı
        function checkOrder() {
            const currentList = Array.from(sortableList.children);
            let isCorrect = true;

            // correctOrder.length artık 7 olacak
            if (currentList.length !== correctOrder.length) {
                isCorrect = false; // Güvenlik kontrolü
            } else {
                for (let i = 0; i < correctOrder.length; i++) {
                    if (currentList[i].dataset.id !== correctOrder[i].id) {
                        isCorrect = false;
                        break;
                    }
                }
            }

            if (isCorrect) {
                feedbackElement.textContent = '✅ Tebrikler! Sıralama Doğru. Yolculuğun aşamalarını çok iyi biliyorsunuz.';
                feedbackElement.className = 'text-center text-xl mt-6 font-semibold text-[#4CAF50]';
            } else {
                feedbackElement.textContent = '❌ Tekrar Deneyin. Kartların yerleşimi doğru değil.';
                feedbackElement.className = 'text-center text-xl mt-6 font-semibold text-red-500';
            }
        }

        // Oyunu başlatma/sıfırlama fonksiyonu
        function resetGame() {
            const randomizedStages = shuffleArray([...correctOrder]); // Kopya oluştur ve karıştır
            renderList(randomizedStages);
            feedbackElement.textContent = '';
            feedbackElement.className = 'text-center text-xl mt-6 font-semibold';
        }

        // Sayfa yüklendiğinde ilk görünümü ayarla
        document.addEventListener('DOMContentLoaded', () => {
             switchView('infographic');
        });
    </script>
</body>
</html>
"
}

