    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;900&display=swap" rel="stylesheet">
    <style>
        /* Ana Stil */
        body {
            font-family: 'Inter', sans-serif;
            background-color: #0c1a2c; /* Deep Night Blue */
            color: #e2e8f0;
            min-height: 100vh;
        }
        /* Olay kartları için genel stil */
        .event-card {
            background-color: #1a273b; 
            padding: 24px;
            border-radius: 16px; 
            transition: all 0.3s ease;
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
            border-bottom: 5px solid; 
            margin-bottom: 24px; 
            position: relative;
            overflow: hidden;
            display: flex;
            flex-direction: column;
        }
        .event-card:hover {
            box-shadow: 0 15px 40px rgba(0, 0, 0, 0.8);
            transform: translateY(-5px); 
        }

        /* Yıl Etiketi Stili */
        .year-label {
            position: absolute;
            top: 0;
            right: 0;
            background-color: rgba(59, 130, 246, 0.9);
            color: white;
            padding: 4px 16px;
            font-weight: 800;
            font-size: 1.125rem;
            border-bottom-left-radius: 16px;
            z-index: 10;
        }

        /* Renkler */
        .color-initial { border-color: #FFD700; } 
        .color-persecution { border-color: #EF4444; } 
        .color-transition { border-color: #3B82F6; } 
        .color-victory { border-color: #10B981; } 
        .color-final { border-color: #F97316; } 

        .text-initial { color: #FFD700; }
        .text-persecution { color: #EF4444; }
        .text-transition { color: #3B82F6; }
        .text-victory { color: #10B981; }
        .text-final { color: #F97316; }

        /* Sıralama Etkinliği Listesi */
        #sortable-list li {
            background-color: #1f2a3e;
            padding: 15px;
            margin-bottom: 8px;
            border-radius: 8px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            border-left: 5px solid #60a5fa;
            cursor: grab; /* Sürükleme imleci */
            transition: background-color 0.2s, transform 0.2s;
        }

        #sortable-list li:hover {
            background-color: #2c3a50;
        }

        /* Sürükle-Bırak Stilleri */
        .dragging {
            opacity: 0.4;
            border: 2px dashed #60a5fa;
            background-color: #1a273b !important;
            box-shadow: none;
        }

        /* Yeni Eklenen Görsel İpucu Stilleri */
        .drag-over-above {
            border-top: 5px solid #a855f7; /* Üstte mor çizgi */
            margin-top: 0px;
        }
        .drag-over-below {
            border-bottom: 5px solid #a855f7; /* Altta mor çizgi */
            margin-bottom: 0px;
        }

        /* Yeni Sekme Stilleri */
        .tab-button {
            padding: 8px 16px; /* Daha küçük padding */
            font-weight: 600;
            transition: all 0.3s;
            color: #9ca3af; /* İnaktif renk */
            border-bottom: 4px solid transparent; /* Sekme alt çizgisi */
            margin-bottom: -1px; /* Alt çizgiyi nav border'ı üzerine oturtmak için */
            font-size: 0.9rem; /* Küçültülmüş yazı boyutu */
