<script>
    /* --- EKRAN AYARLARI VE ZOOM --- */
    let currentScale = 1;
    let manualZoom = 0;

    function fitScreen() {
        if(window.innerWidth > 1024) {
            const container = document.getElementById('app-container');
            const targetWidth = 1540;
            const targetHeight = 890;
            const winWidth = window.innerWidth;
            const winHeight = window.innerHeight;

            let scale = Math.min(winWidth / targetWidth, winHeight / targetHeight);
            currentScale = scale + manualZoom;

            container.style.transform = `scale(${currentScale})`;
        } else {
            document.getElementById('app-container').style.transform = 'none';
        }
    }

    function zoomIn() { manualZoom += 0.1; fitScreen(); }
    function zoomOut() { if(currentScale > 0.3) { manualZoom -= 0.1; fitScreen(); } }
    function toggleFullScreen() {
        if (!document.fullscreenElement) { document.documentElement.requestFullscreen(); }
        else { if (document.exitFullscreen) { document.exitFullscreen(); } }
    }

    window.addEventListener('resize', fitScreen);
    window.addEventListener('load', fitScreen);

    /* --- İÇERİK VERİSİ --- */
    const units = [
        // 2.1 HAC İBADETİ
        {
            title: "2.1 İslam'da Hac İbadeti",
            slides: [
                {
                    title: "Hac Nedir?",
                    content: `<p><strong>Hac:</strong> İmkânı olan Müslümanların zilhicce ayında ihram giyerek, Arafat'ta vakfe yaparak ve Kâbe'yi tavaf ederek yaptıkları <strong>farz</strong> ibadettir.</p>
                    <p>Hicretin 9. yılında farz kılınmıştır. Hem mal hem de beden ile yapılan bir ibadettir.</p>
                    <div class="quote">"Yolculuğuna gücü yetenlerin haccetmesi, Allah'ın insanlar üzerinde bir hakkıdır." (Al-i İmran, 97)</div>`,
                    icon: "🕋", activityType: "quiz", activityTitle: "Hac Bilgisi",
                    activityData: [{q:"Hac ne zaman yapılır?", options:["Ramazan Ayında", "Zilhicce Ayında"], a:"Zilhicce Ayında"}, {q:"Hac nasıl bir ibadettir?", options:["Sadece bedenle", "Hem mal hem bedenle"], a:"Hem mal hem bedenle"}]
                },
                {
                    title: "Haccın Önemi",
                    content: `<ul style="line-height:1.8;">
                    <li>Allah'ın rızasını kazanmak için yapılır.</li>
                    <li>Mahşer gününün provasıdır (Arafat'ta toplanma).</li>
                    <li>Günahlardan arınma vesilesidir.</li>
                    <li>Dünya Müslümanlarının kardeşlik buluşmasıdır.</li>
                    <li>İhram ile makam ve mevkilerin geçiciliği anlaşılır.</li></ul>`,
                    icon: "🤝", activityType: "none", activityTitle: "", activityData: null
                }
            ]
        },
        // 2.2 HACCIN YAPILIŞI
        {
            title: "2.2 Haccın Yapılışı ve Kavramlar",
            slides: [
                {
                    title: "Kavramları Öğrenelim",
                    content: `<p><strong>İhram:</strong> Hac için giyilen dikişsiz beyaz kıyafet ve yasaklar bütünü.<br>
                    <strong>Tavaf:</strong> Kâbe'nin etrafında 7 kez dönmek (Her dönüşe Şavt denir).<br>
                    <strong>Say:</strong> Safa ve Merve tepeleri arasında 7 kez gidip gelmek.<br>
                    <strong>Vakfe:</strong> Arafat'ta bir süre durmak ve dua etmek.</p>`,
                    icon: "📖", activityType: "matching", activityTitle: "Kavram Eşleştirme",
                    activityData: [{term:"Tavaf", def:"Kâbe etrafında dönmek"}, {term:"Say", def:"Safa-Merve arası yürüyüş"}, {term:"Vakfe", def:"Arafat'ta beklemek"}, {term:"Şavt", def:"Kâbe etrafında 1 tur"}]
                },
                {
                    title: "Haccın Mekânları",
                    content: `<p><strong>Mikat:</strong> İhrama girilen sınırlar.<br>
                    <strong>Arafat:</strong> Arife günü vakfe yapılan yer.<br>
                    <strong>Müzdelife:</strong> Arafat ile Mina arasında vakfe yapılan ve taş toplanan yer.<br>
                    <strong>Mina:</strong> Şeytan taşlanan ve kurban kesilen yer.</p>`,
                    icon: "📍", activityType: "matching", activityTitle: "Mekânları Tanı",
                    activityData: [{term:"Mina", def:"Şeytan taşlama yeri"}, {term:"Arafat", def:"Vakfe yeri"}, {term:"Mikat", def:"İhram sınırı"}, {term:"Müzdelife", def:"Taş toplama yeri"}]
                },
                {
                    title: "Haccın Yapılış Sırası",
                    content: `<p>Hac ibadeti belirli bir sıra ile yapılır:</p>
                    1. Mikat sınırında İhrama girilir.<br>
                    2. Arife günü Arafat Vakfesi yapılır (Farz).<br>
                    3. Müzdelife Vakfesi yapılır.<br>
                    4. Mina'da Şeytan taşlanır ve Kurban kesilir.<br>
                    5. Tıraş olunup ihramdan çıkılır.<br>
                    6. Kâbe'de Ziyaret Tavafı yapılır (Farz).`,
                    icon: "🔢", activityType: "ordering", activityTitle: "Sıralama Yap",
                    activityData: ["İhrama Girmek", "Arafat Vakfesi", "Müzdelife Vakfesi", "Şeytan Taşlama/Kurban", "Ziyaret Tavafı"]
                }
            ]
        },
        // 2.3 UMRE
        {
            title: "2.3 Umre ve Önemi",
            slides: [
                {
                    title: "Umre Nedir?",
                    content: `<p>Hac mevsimi dışında, ihramlı olarak Kâbe'yi tavaf edip Safa-Merve arasında say yaptıktan sonra tıraş olarak yapılan ibadettir. <strong>Sünnettir.</strong></p>
                    <p>Umreye "Küçük Hac" da denir.</p>`,
                    icon: "🌍", activityType: "none", activityTitle: "", activityData: null
                },
                {
                    title: "Hac ve Umre Farkı",
                    content: `<table class="concept-table"><tr><th>HAC</th><th>UMRE</th></tr>
                    <tr><td>Yılda 1 kez (Zilhicce)</td><td>Her zaman yapılabilir</td></tr>
                    <tr><td>Farzdır</td><td>Sünnettir</td></tr>
                    <tr><td>Vakfe, Şeytan Taşlama, Kurban VAR</td><td>Vakfe, Şeytan Taşlama, Kurban YOK</td></tr>
                    </table>`,
                    icon: "⚖️", activityType: "quiz", activityTitle: "Farkları Bul",
                    activityData: [{q:"Hangisi sadece Hac'da vardır?", options:["Tavaf", "Vakfe"], a:"Vakfe"}, {q:"Umre ne zaman yapılır?", options:["Sadece Ramazanda", "Her zaman"], a:"Her zaman"}]
                }
            ]
        },
        // 2.4 KURBAN
        {
            title: "2.4 Kurban İbadeti",
            slides: [
                {
                    title: "Kurban Nedir?",
                    content: `<p>Allah'a yaklaşmak ve rızasını kazanmak amacıyla belirli günlerde (Kurban Bayramı) belirli hayvanları kesmektir. Hükmü <strong>Vacip</strong>tir.</p>
                    <div class="quote">"Onların ne etleri ne de kanları Allah'a ulaşır; fakat O'na sadece sizin takvanız ulaşır." (Hac, 37)</div>`,
                    icon: "🐑", activityType: "none", activityTitle: "", activityData: null
                },
                {
                    title: "Kurbanlık Hayvanlar",
                    content: `<ul style="line-height:1.8;">
                    <li><strong>Koyun/Keçi:</strong> 1 yaşını doldurmuş olmalı. 1 kişi adına kesilir.</li>
                    <li><strong>Sığır/Manda:</strong> 2 yaşını doldurmuş olmalı. 1-7 kişi ortak olabilir.</li>
                    <li><strong>Deve:</strong> 5 yaşını doldurmuş olmalı. 1-7 kişi ortak olabilir.</li></ul>
                    <p>Tavuk, horoz gibi hayvanlardan kurban olmaz.</p>`,
                    icon: "🐄", activityType: "matching", activityTitle: "Hayvan Yaşları",
                    activityData: [{term:"Koyun", def:"1 Yaş"}, {term:"Sığır", def:"2 Yaş"}, {term:"Deve", def:"5 Yaş"}, {term:"Tavuk", def:"Kurban Olmaz"}]
                },
                {
                    title: "Kurban Çeşitleri ve Faydaları",
                    content: `<p><strong>Adak (Nezir):</strong> Bir dilek gerçekleşince kesilen kurban.<br>
                    <strong>Akika:</strong> Çocuk doğunca şükür için kesilen kurban.</p>
                    <p><strong>Faydaları:</strong> Allah'a yakınlaşma, cimrilikten kurtulma, toplumsal yardımlaşma (et dağıtımı).</p>`,
                    icon: "❤️", activityType: "quiz", activityTitle: "Kurban Bilgisi",
                    activityData: [{q:"Yeni doğan çocuk için kesilen kurban?", options:["Adak", "Akika"], a:"Akika"}, {q:"Kurban etinin dağıtılması neyi sağlar?", options:["Yardımlaşmayı", "İsrafı"], a:"Yardımlaşmayı"}]
                }
            ]
        },
        // 2.5 HZ. İSMAİL
        {
            title: "2.5 Bir Peygamber: Hz. İsmail (as)",
            slides: [
                {
                    title: "Hacer ve İsmail",
                    content: `<p>Hz. İbrahim, eşi Hacer ve oğlu İsmail'i Mekke'nin ıssız çölüne bıraktı. Su bitince Hz. Hacer, Safa ve Merve arasında 7 kez koştu (Say ibadeti buradan gelir). Sonunda İsmail'in ayağının dibinden <strong>Zemzem</strong> suyu çıktı.</p>`,
                    icon: "💧", activityType: "none", activityTitle: "", activityData: null
                },
                {
                    title: "Kurban İmtihanı ve Kâbe",
                    content: `<p>Hz. İbrahim rüyasında oğlunu kurban etmesi istendi. İkisi de buna teslim oldu. Allah, sadakatleri karşılığında onlara bir kurbanlık gönderdi.</p>
                    <p>Daha sonra baba-oğul birlikte Allah'ın emriyle <strong>Kâbe'yi inşa ettiler</strong>.</p>`,
                    icon: "🏗️", activityType: "ordering", activityTitle: "Hikayeyi Sırala",
                    activityData: ["Mekke çölüne bırakılmaları", "Zemzem suyunun çıkması", "Kurban imtihanı", "Kâbe'nin inşası"]
                }
            ]
        },
        // 2.6 ENAM SURESİ 162
        {
            title: "2.6 Bir Ayet: Enam 162",
            slides: [
                {
                    title: "Ayet ve Anlamı",
                    content: `<div class="info-card"><span class="arabic-text">قُلْ اِنَّ صَلَات۪ي وَنُسُك۪ي وَمَحْيَايَ وَمَمَات۪ي لِلّٰهِ رَبِّ الْعَالَم۪ينَۙ</span></div>
                    <p><strong>Okunuşu:</strong> Kul inne salâtî ve nüsukî ve mahyâye ve memâtî lillâhi rabbil âlemîn.</p>
                    <p><strong>Anlamı:</strong> De ki: "Şüphesiz benim namazım, kurbanım (ibadetlerim), hayatım ve ölümüm hepsi âlemlerin Rabbi Allah içindir."</p>`,
                    icon: "🤲", activityType: "ordering", activityTitle: "Anlamı Sırala",
                    activityData: ["Benim namazım,", "ibadetlerim,", "hayatım ve ölümüm", "âlemlerin Rabbi Allah içindir."]
                }
            ]
        }
    ];

    /* --- DURUM YÖNETİMİ --- */
    let currentUnitIdx = 0;
    let currentSlideIdx = 0;

    // Oyun Değişkenleri
    let currentData = null;
    let selectedItem = null;
    let anagramIndex = 0;
    let currentAnagramState = { word:"", pos:0 };

    /* --- GÖRÜNÜM KONTROLÜ --- */
    function init() {
        fitScreen();
        window.addEventListener('resize', fitScreen);
    }

    function selectUnit(index) {
        currentUnitIdx = index;
        currentSlideIdx = 0;
        document.getElementById('menu-screen').style.display = 'none';
        document.getElementById('unit-screen').style.display = 'flex';
        document.getElementById('unit-title').textContent = units[index].title;
        renderSlide();
    }

    function returnToMenu() {
        document.getElementById('unit-screen').style.display = 'none';
        document.getElementById('menu-screen').style.display = 'flex';
    }

    function renderSlide() {
        const slide = units[currentUnitIdx].slides[currentSlideIdx];
        const container = document.getElementById('slide-container');
        document.getElementById('current-page').innerText = currentSlideIdx + 1;
        document.getElementById('prev-btn').disabled = currentSlideIdx === 0;
        document.getElementById('next-btn').disabled = currentSlideIdx === units[currentUnitIdx].slides.length - 1;

        let btnHtml = slide.activityType !== "none"
            ? `<button class="activity-btn" onclick="openActivity()">🎮 ETKİNLİK BAŞLAT</button>` 
            : `<div style="text-align:center; color:#fbbf24; font-size:1.4rem; margin-top:20px;">Okudum, Anladım ✅</div>`;

        container.innerHTML = `
            <div class="text-panel"><h2>${slide.title}</h2>${slide.content}</div>
            <div class="visual-panel"><div class="visual-icon">${slide.icon}</div>${btnHtml}</div>
        `;
    }

    function nextSlide() { if(currentSlideIdx < units[currentUnitIdx].slides.length-1) { currentSlideIdx++; renderSlide(); } }
    function prevSlide() { if(currentSlideIdx > 0) { currentSlideIdx--; renderSlide(); } }

    /* --- ETKİNLİK MOTORU --- */
    function openActivity() {
        const slide = units[currentUnitIdx].slides[currentSlideIdx];
        const board = document.getElementById('game-board');
        document.getElementById('activity-overlay').style.display = 'flex';
        document.getElementById('activity-title').textContent = slide.activityTitle;
        document.getElementById('feedback').textContent = "";
        board.innerHTML = "";
        currentData = slide.activityData;

        if(slide.activityType === 'quiz') loadQuiz(board, currentData);
        else if(slide.activityType === 'matching') loadMatching(board, currentData);
        else if(slide.activityType === 'ordering') loadOrdering(board, currentData);
        else if(slide.activityType === 'anagram') { anagramIndex=0; loadAnagram(board, currentData); }
    }

    function closeActivity() { document.getElementById('activity-overlay').style.display = 'none'; }

    // 1. QUIZ
    function loadQuiz(board, data) {
        const show = (idx) => {
            if(idx >= data.length) { board.innerHTML="<h2 class='success'>Tamamladın! 🎉</h2>"; return; }
            let q = data[idx];
            board.innerHTML = `<h3 style="font-size:1.8rem; text-align:center;">${q.q}</h3><div id="opts" style="width:100%; display:flex; flex-direction:column; align-items:center;"></div>`;
            q.options.forEach(opt => {
                let btn = document.createElement("div"); btn.className = "quiz-option"; btn.textContent = opt;
                btn.onclick = function() { 
                    if(opt === q.a) { this.style.background="#059669"; setTimeout(()=>show(idx+1), 600); }
                    else { this.style.background="#dc2626"; }
                };
                document.getElementById('opts').appendChild(btn);
            });
        };
        show(0);
    }

    // 2. EŞLEŞTİRME (YATAY DÜZEN)
    function loadMatching(board, data) {
        board.innerHTML = `<div class="match-container"><div class="match-col" id="left"></div><div class="match-col" id="right"></div></div>`;
        let leftCol = document.getElementById('left');
        let rightCol = document.getElementById('right');

        let rightItems = [...data].sort(() => Math.random() - 0.5);

        data.forEach(item => {
            let btn = document.createElement('div'); btn.className = 'match-item'; 
            btn.textContent = item.term; btn.dataset.pair = item.def;
            btn.onclick = () => selectLeft(btn); leftCol.appendChild(btn);
        });

        rightItems.forEach(item => {
            let btn = document.createElement('div'); btn.className = 'match-item'; 
            btn.textContent = item.def;
            btn.onclick = () => checkMatch(btn); rightCol.appendChild(btn);
        });
    }

    function selectLeft(elem) {
        if(elem.classList.contains('matched')) return;
        document.querySelectorAll('#col-left .match-item').forEach(e => e.classList.remove('selected'));
        elem.classList.add('selected'); selectedItem = elem;
    }

    function checkMatch(elem) {
        if(!selectedItem || elem.classList.contains('matched')) return;
        const feedback = document.getElementById('feedback');
        if(selectedItem.dataset.pair === elem.textContent) {
            elem.classList.add('matched'); selectedItem.classList.add('matched'); selectedItem.classList.remove('selected'); selectedItem = null;
            feedback.innerHTML = "<span class='success'>Doğru!</span>";
            if(document.querySelectorAll('#col-left .match-item:not(.matched)').length === 0) feedback.innerHTML = "<span class='success'>Tebrikler!</span>";
        } else {
            elem.classList.add('wrong'); setTimeout(() => elem.classList.remove('wrong'), 500);
            feedback.innerHTML = "<span class='error'>Yanlış!</span>";
        }
    }

    // 3. SIRALAMA
    function loadOrdering(board, data) {
        board.innerHTML = `<p style="text-align:center; font-size:1.5rem;">Sırasıyla seç:</p><div id="sort-area" class="sort-container"></div>`;
        let area = document.getElementById('sort-area');
        let shuffled = [...data].sort(()=>Math.random()-0.5);
        let step = 0;

        shuffled.forEach(txt => {
            let div = document.createElement('div'); div.className = 'sort-item'; div.textContent = txt;
            div.onclick = function() {
                if(txt === data[step]) {
                    this.style.background = '#059669'; this.style.pointerEvents='none'; step++;
                    if(step === data.length) document.getElementById('feedback').innerHTML="<span class='success'>Tebrikler!</span>";
                } else {
                    this.style.background = '#dc2626'; setTimeout(()=>this.style.background='#451a03', 500);
                }
            };
            area.appendChild(div);
        });
    }

    // 4. ANAGRAM
    function loadAnagram(board, data) {
        if(anagramIndex >= data.length) { board.innerHTML="<h2 class='success'>Bitti! 🎉</h2>"; return; }
        let item = data[anagramIndex];
        currentAnagramState = { word: item.answer, pos: 0 };
        board.innerHTML = `<div class="anagram-container"><div style="margin-bottom:20px; color:#93c5fd; font-size:1.5rem;">İpucu: ${item.hint}</div><div id="slots" class="anagram-slots"></div><div id="pool" class="letter-pool"></div></div>`;

        for(let i=0; i<item.answer.length; i++) {
            let s = document.createElement('div'); s.className='anagram-slot'; s.id=`s-${i}`; document.getElementById('slots').appendChild(s);
        }
        item.scrambled.split('').forEach(char => {
            let btn = document.createElement('button'); btn.className='letter-btn'; btn.textContent=char;
            btn.onclick = function() {
                if(char === currentAnagramState.word[currentAnagramState.pos]) {
                    document.getElementById(`s-${currentAnagramState.pos}`).textContent = char;
                    this.classList.add('correct'); currentAnagramState.pos++;
                    if(currentAnagramState.pos >= item.answer.length) { anagramIndex++; setTimeout(()=>loadAnagram(board, data), 1000); }
                } else {
                    this.classList.add('wrong'); setTimeout(()=>this.classList.remove('wrong'), 400);
                }
            };
            document.getElementById('pool').appendChild(btn);
        });
    }

    // Başlat
    init();
</script>
</body>
</html>"
}

