</head>
<body>

<!-- KONTROL BUTONLARI -->
<div id="display-controls">
    <button class="ctrl-btn ctrl-btn-blue" onclick="toggleFullScreen()" title="Tam Ekran">⛶</button>
    <button class="ctrl-btn" onclick="zoomOut()" title="Küçült">-</button>
    <button class="ctrl-btn" onclick="zoomIn()" title="Büyüt">+</button>
</div>

<div id="app-wrapper">
    <div id="app-container">
        <!-- MENÜ EKRANI -->
        <div id="menu-screen">
            <h1 class="menu-title">1. Ünite: Peygamber ve İlahi Kitap</h1>
            <div class="menu-grid">
                <div class="menu-btn" onclick="selectUnit(0)">
                    <span class="menu-icon">🌱</span>
                    <div class="menu-text"><h3>1.1 İnsanlara Rehber: Peygamber</h3><p>Peygamberlik, Resul, Nebi, Özellikler</p></div>
                </div>
                <div class="menu-btn" onclick="selectUnit(1)">
                    <span class="menu-icon">💡</span>
                    <div class="menu-text"><h3>1.2 Peygamberlerin Mesajı: Vahiy</h3><p>Vahyin amacı, Ayetler, Kıssalar</p></div>
                </div>
