                    <span class="menu-icon">📚</span>
                    <div class="menu-text"><h3>1.3 İlahi Kitaplar</h3><p>Tevrat, Zebur, İncil, Kur'an, Suhuf</p></div>
                </div>
                <div class="menu-btn" onclick="selectUnit(3)">
                    <span class="menu-icon">🤲</span>
                    <div class="menu-text"><h3>1.4 Bir Sure: Felak Suresi</h3><p>Tüm ayetler, Anlamı, Mesajlar</p></div>
                </div>
            </div>
        </div>

        <!-- ÜNİTE EKRANI -->
        <div id="unit-screen" style="display:none; flex-direction:column; height:100%;">
            <div class="header-bar">
                <div style="display:flex; align-items:center; gap:15px; width:100%; justify-content:space-between;">
                    <button class="home-btn" onclick="returnToMenu()">🏠 Menü</button>
                    <div class="header-title" id="unit-title">Başlık</div>
                    <div class="progress-indicator" style="font-size:1.1rem;">Sf <span id="current-page">1</span></div>
                </div>
            </div>

            <div id="slide-container" class="slide-content"></div>

            <div class="controls-bar">
                <button id="prev-btn" class="nav-btn" onclick="prevSlide()">❮ Geri</button>
                <button id="next-btn" class="nav-btn" onclick="nextSlide()">İleri ❯</button>
            </div>
        </div>

        <!-- OYUN MODALI -->
        <div id="activity-overlay">
            <button class="close-activity" onclick="closeActivity()">✕</button>
            <div class="activity-header" id="activity-title">Etkinlik</div>
            <div class="game-area" id="game-board"></div>
            <div class="feedback-msg" id="feedback"></div>
        </div>
    </div>
</div>

<script>
    /* --- EKRAN AYARLARI VE ZOOM --- */
    let currentScale = 1;
    let manualZoom = 0;

    function fitScreen() {
        if(window.innerWidth > 1024) {
            const container = document.getElementById('app-container');
            const targetWidth = 1540;
            const targetHeight = 890;
            const winWidth = window.innerWidth;
            const winHeight = window.innerHeight;

            let scale = Math.min(winWidth / targetWidth, winHeight / targetHeight);
            currentScale = scale + manualZoom;

            container.style.transform = `scale(${currentScale})`;
        } else {
            document.getElementById('app-container').style.transform = 'none';
        }
    }

    function zoomIn() { manualZoom += 0.1; fitScreen(); }
    function zoomOut() { if(currentScale > 0.3) { manualZoom -= 0.1; fitScreen(); } }
    function toggleFullScreen() {
        if (!document.fullscreenElement) { document.documentElement.requestFullscreen(); }
        else { if (document.exitFullscreen) { document.exitFullscreen(); } }
    }

    window.addEventListener('resize', fitScreen);
    window.addEventListener('load', fitScreen);

    /* --- İÇERİK VERİSİ --- */
    const units = [
        // ÜNİTE 1.1: PEYGAMBERLER
        {
            title: "1.1 İnsanlara Rehber: Peygamber",
            slides: [
                {
                    title: "Üniteye Başlarken: Hz. İbrahim Kıssası",
                    content: `<p>Babillilerin senede bir gün kutladıkları bir bayramları vardı. Kırlara gider, eğlenirlerdi. Azer, oğlu İbrahim’in de eğlenceye katılmasını istedi ama İbrahim (as) gitmedi.</p>
                    <div class="story-card">
                        <strong>1. GİRİŞ:</strong> Şehir boşalınca tapınağa gitti. Eline bir balta alarak bütün heykelleri tek tek kırdı ama <strong>en büyük puta dokunmadı</strong>. Baltayı o büyük putun boynuna asıp oradan ayrıldı.<br><br>
                        <strong>2. SORGULAMA:</strong> Halk döndü. "Bunu sen mi yaptın?" dediler. İbrahim: "Belki şu büyük olan yapmıştır, ona sorun!" dedi.<br><br>
                        <strong>3. DERS:</strong> Halk "Put konuşamaz ki!" deyince Hz. İbrahim taşı gediğine koydu: <em>"Konuşamayan, kendini koruyamayan taşa neden tapıyorsunuz?"</em>
                    </div>`,
                    icon: "🪓", activityType: "ordering", activityTitle: "Olayları Sırala",
                    activityData: ["Hz. İbrahim bayrama gitmedi.", "Tapınaktaki putları kırdı.", "Baltayı büyük putun boynuna astı.", "Halk putların kırıldığını gördü.", "İbrahim 'Belki büyük put yapmıştır' dedi."]
                },
                {
                    title: "Tanımlar: Peygamber, Resul ve Nebi",
                    content: `<p><span style="color:#fbbf24;font-weight:bold">Peygamber:</span> Farsça kökenli olup "Haber getiren" demektir. Terim olarak; Allah'ın emir, yasak ve öğütlerini insanlara bildirmekle görevli elçilerdir.</p>
                    <p><strong>Vahiy:</strong> Yüce Allah'ın emir ve hükümlerini peygamberlere bildirmesidir.<br><strong>Tebliğ:</strong> Peygamberlerin bu vahiyleri insanlara olduğu gibi iletmesidir.</p>
                    <table class="concept-table"><tr><th>KAVRAM</th><th>ANLAMI</th></tr><tr><td>RESUL</td><td>Kendisine <strong>yeni bir kitap</strong> verilen elçidir. (Anlamı: Elçi)</td></tr><tr><td>NEBİ</td><td>Kendisine kitap verilmeyen, <strong>önceki kitabını</strong> devam ettiren peygamberdir. (Anlamı: Haberci)</td></tr></table>`,
                    icon: "📖", activityType: "matching", activityTitle: "Kavramları Eşleştir",
                    activityData: [{term:"Resul", def:"Kendisine kitap gönderilen elçi"}, {term:"Nebi", def:"Haberci anlamına gelen peygamber"}, {term:"Vahiy", def:"Allah'ın mesajını peygambere iletmesi"}, {term:"Tebliğ", def:"Peygamberin mesajı insanlara duyurması"}]
                },
                {
                    title: "Kur'an'da Adı Geçen Peygamberler",
                    content: `<p>Yüce Allah tarih boyunca birçok peygamber göndermiştir. Kur'an'da ismi geçen peygamber sayısı <strong>25</strong>'tir.</p>
