        </div>

        <!-- ÜNİTE EKRANI -->
        <div id="unit-screen" style="display:none; flex-direction:column; height:100%;">
            <div class="header-bar">
                <div style="display:flex; align-items:center; gap:15px; width:100%; justify-content:space-between;">
                    <button class="home-btn" onclick="window.appFunctions.returnToMenu()">🏠 Menü</button>
                    <div class="header-title" id="unit-title">Başlık</div>
                    <div class="progress-indicator" style="font-size:1.1rem;">Sf <span id="current-page">1</span></div>
                </div>
            </div>

            <div id="slide-container" class="slide-content"></div>

            <div class="controls-bar">
                <button id="prev-btn" class="nav-btn" onclick="window.appFunctions.prevSlide()">❮ Geri</button>
                <button id="next-btn" class="nav-btn" onclick="window.appFunctions.nextSlide()">İleri ❯</button>
            </div>
        </div>

        <!-- OYUN MODALI -->
        <div id="activity-overlay">
            <button class="close-activity" onclick="window.appFunctions.closeActivity()">✕</button>
            <div class="activity-header" id="activity-title">Etkinlik</div>
            <div class="game-area" id="game-board"></div>
            <div class="feedback-msg" id="feedback"></div>
        </div>
    </div>
</div>

<script>
{
    /* --- EKRAN AYARLARI VE ZOOM --- */
    let currentScale = 1;
    let manualZoom = 0;

    function fitScreen() {
        if(window.innerWidth > 1024) {
            const container = document.getElementById('app-container');
            const targetWidth = 1540;
            const targetHeight = 890;
            const winWidth = window.innerWidth;
            const winHeight = window.innerHeight;

            let scale = Math.min(winWidth / targetWidth, winHeight / targetHeight);
            currentScale = scale + manualZoom;

            container.style.transform = `scale(${currentScale})`;
        } else {
            document.getElementById('app-container').style.transform = 'none';
        }
    }

    /* --- İÇERİK VERİSİ --- */
    const units = [
        // 1. GÖRÜLEN VE GÖRÜLEMEYEN VARLIKLAR
        {
            title: "1. Görülen ve Görülemeyen Varlıklar",
            slides: [
                {
                    title: "Varlıklar Âlemi",
                    content: `<p>Dünya görsel bir şölendir. Bazı varlıkları (Güneş, dağ, insan) gözle görürüz. Bazılarını ise (mikroorganizma, uzaydaki yıldızlar) teknoloji ile görürüz. Ancak bir de gözle görülemeyen varlıklar vardır.</p>
                    <div class="info-card"><strong>Âlem:</strong> Allah'ın (cc) dışındaki tüm varlıklara denir.</div>
                    <div class="info-card"><strong>Gayb:</strong> Gözle görülemeyen, duyularla bilinemeyen, sadece Allah'ın bildirmesiyle bilinen âlemdir.</div>`,
                    icon: "🌌", activityType: "ordering", activityTitle: "Varlıkları Sınıflandır (Zihinden)",
                    activityData: ["Görülen: İnsan, Ağaç", "Görülemeyen: Melek, Cin, Şeytan, Akıl, Sevgi"]
                },
                {
                    title: "Cinler ve Şeytan",
                    content: `<p><strong>Cin:</strong> Ateşten yaratılmış, irade sahibi, görülemeyen varlıklardır. İnsanlar gibi Allah'a kulluk için yaratılmışlardır.</p>
                    <p><strong>Şeytan:</strong> Ateşten yaratılan, Hz. Adem'e secde etmeyip kibirlenen ve Allah'ın huzurundan kovulan varlıktır. İnsanlara sadece vesvese verebilir, zorla kötülük yaptıramaz.</p>`,
                    icon: "🔥", activityType: "quiz", activityTitle: "Doğru mu Yanlış mı?",
                    activityData: [{q:"Şeytan insanlara zorla kötülük yaptırabilir.", options:["Doğru", "Yanlış"], a:"Yanlış"}, {q:"Cinler ateşten yaratılmıştır.", options:["Doğru", "Yanlış"], a:"Doğru"}]
                },
                {
                    title: "Batıl İnançlar",
                    content: `<p><strong>Hurafe:</strong> Akla ve dine aykırı uydurma sözlerdir (Örn: Nazar boncuğu, fal, ruh çağırma).</p><p>Sihir ve falcılık dinimizce yasaklanmıştır. Geleceği sadece Allah bilir.</p>`,
                    icon: "🚫", activityType: "none", activityTitle: "", activityData: null
                }
            ]
        },
        // 2. MELEKLER
        {
            title: "2. Melekler ve Özellikleri",
            slides: [
                {
                    title: "Melek Nedir?",
                    content: `<p>Nurdan yaratılmış, yeme-içme, cinsiyet, uyuma gibi özellikleri olmayan, Allah'a tam itaat eden varlıklardır. Gözle görülmezler ancak peygamberler vahiy yoluyla bildirmiştir.</p>
                    <div class="quote">"İman; Allah'a, meleklerine... inanmandır." (Hadis)</div>`,
                    icon: "🪽", activityType: "quiz", activityTitle: "Melek Özellikleri",
                    activityData: [{q:"Meleklerin cinsiyeti var mıdır?", options:["Evet", "Hayır"], a:"Hayır"}, {q:"Melekler neden yaratılmıştır?", options:["Ateş", "Nur", "Toprak"], a:"Nur"}]
                },
                {
                    title: "Dört Büyük Melek",
                    content: `<table class="concept-table">
                    <tr><th>Melek</th><th>Görevi</th></tr>
                    <tr><td><strong>Cebrail (as)</strong></td><td>Vahiy meleği. Emirleri peygamberlere iletir.</td></tr>
                    <tr><td><strong>Azrail (as)</strong></td><td>Ölüm meleği. Canları alır.</td></tr>
                    <tr><td><strong>Mikâil (as)</strong></td><td>Doğa olaylarını ve rızkı düzenler.</td></tr>
                    <tr><td><strong>İsrafil (as)</strong></td><td>Sûra üflemekle görevlidir (Kıyamet).</td></tr>
                    </table>`,
                    icon: "📜", activityType: "matching", activityTitle: "Melekleri Eşleştir",
                    activityData: [{term:"Cebrail", def:"Vahiy"}, {term:"Azrail", def:"Ölüm"}, {term:"Mikâil", def:"Doğa Olayları"}, {term:"İsrafil", def:"Sûr'a üflemek"}]
                },
                {
                    title: "Diğer Melekler",
                    content: `<p><strong>Kiramen Kâtibin:</strong> Yazıcı melekler. Sağ ve solumuzda iyilik ve kötülükleri yazarlar.</p>
                    <p><strong>Münker ve Nekir:</strong> Sorgu melekleri. Kabirde insanı sorgularlar.</p>
                    <p><strong>Hafaza:</strong> Koruyucu melekler.</p>`,
                    icon: "✍️", activityType: "matching", activityTitle: "Diğer Melekler",
                    activityData: [{term:"Kiramen Kâtibin", def:"Yazıcı"}, {term:"Münker-Nekir", def:"Sorgu"}, {term:"Hafaza", def:"Koruyucu"}]
                }
            ]
        },
        // 3. DÜNYA VE AHİRET
        {
            title: "3. Dünya ve Ahiret Hayatı",
            slides: [
                {
                    title: "Hayatın Amacı",
                    content: `<p>Dünya hayatı geçici, ahiret hayatı ise sonsuzdur. Dünya, ahiretin tarlasıdır. İnsan, Allah'a kulluk etmek ve imtihan edilmek için yaratılmıştır.</p>
                    <div class="quote">"Dünya hayatı bir oyun ve eğlenceden başka bir şey değildir." (Enam, 32)</div>`,
                    icon: "🌍", activityType: "none", activityTitle: "", activityData: null
                },
                {
                    title: "Ölüm Bir Son Değildir",
                    content: `<p>Ölüm, yok oluş değil, yeni bir hayatın başlangıcıdır. Baharda kuruyan bitkilerin canlanması gibi, insanlar da ahirette yeniden diriltilecektir.</p>`,
                    icon: "🌱", activityType: "quiz", activityTitle: "Kavrama Testi",
                    activityData: [{q:"Dünya hayatı nasıldır?", options:["Sonsuz", "Geçici"], a:"Geçici"}, {q:"Ölüm ne anlama gelir?", options:["Yok oluş", "Ahirete geçiş"], a:"Ahirete geçiş"}]
                }
            ]
        },
        // 4. AHİRET AŞAMALARI
        {
            title: "4. Ahiret Hayatının Aşamaları",
            slides: [
                {
                    title: "1. Ölüm ve Berzah",
                    content: `<p><strong>Ölüm:</strong> Ruhun bedenden ayrılması. Ecel, belirlenen ölüm vaktidir.</p>
                    <p><strong>Berzah (Kabir):</strong> Ölümle diriliş arasındaki bekleme dönemi.</p>`,
                    icon: "⚰️", activityType: "none", activityTitle: "", activityData: null
                },
                {
                    title: "2. Kıyamet ve Diriliş",
                    content: `<p><strong>Kıyamet:</strong> İsrafil (as) 1. kez Sûra üfler, evrenin düzeni bozulur ve her şey ölür.</p>
                    <p><strong>Baas (Diriliş):</strong> İsrafil (as) 2. kez Sûra üfler, herkes yeniden dirilir.</p>`,
                    icon: "🎺", activityType: "none", activityTitle: "", activityData: null
                },
                {
                    title: "3. Mahşer ve Mizan",
                    content: `<p><strong>Haşir/Mahşer:</strong> Dirilen insanların hesap vermek için toplanması (Meydan).</p>
                    <p><strong>Mizan:</strong> İyilik ve kötülüklerin tartıldığı adalet terazisi.</p>`,
                    icon: "⚖️", activityType: "matching", activityTitle: "Kavramları Eşleştir",
                    activityData: [{term:"Kıyamet", def:"Evrenin sonu"}, {term:"Baas", def:"Yeniden Diriliş"}, {term:"Mahşer", def:"Toplanma yeri"}, {term:"Mizan", def:"Tartı/Terazi"}]
                },
                {
                    title: "4. Cennet ve Cehennem",
                    content: `<p><strong>Cennet:</strong> İman edip iyi işler yapanların sonsuz ödül yeri.</p>
                    <p><strong>Cehennem:</strong> İnkâr edenlerin ve günahkarların ceza yeri.</p>`,
                    icon: "🏁", activityType: "ordering", activityTitle: "Sıralama Yap",
                    activityData: ["Ölüm", "Berzah", "Kıyamet", "Diriliş (Baas)", "Mahşer", "Hesap/Mizan", "Cennet/Cehennem"]
                }
            ]
        },
        // 5. İNANCIN ETKİSİ
        {
            title: "5. Ahiret İnancının Etkisi",
            slides: [
                {
                    title: "Davranışlara Etkisi",
                    content: `<p>Ahirete inanan insan:</p><ul><li>Yaptıklarının hesabını vereceğini bilir, kötülükten kaçınır.</li><li>Zorluklara sabreder, ümitsizliğe düşmez.</li><li>Adaletli, merhametli ve dürüst olur.</li><li>"Ne ekersen onu biçersin" bilinciyle yaşar.</li></ul>`,
                    icon: "🧠", activityType: "quiz", activityTitle: "Davranış Analizi",
                    activityData: [{q:"Hesap vereceğini bilen insan nasıl davranır?", options:["Sorumsuzca", "Dikkatli ve dürüst"], a:"Dikkatli ve dürüst"}]
                }
            ]
        },
        // 6. HZ. İSA
        {
            title: "6. Bir Peygamber: Hz. İsa (as)",
            slides: [
                {
                    title: "Doğumu ve Hayatı",
                    content: `<p>Annesi Hz. Meryem'dir. Babasız olarak mucizevi bir şekilde Kudüs'te doğmuştur. Hz. Muhammed'den (sav) önceki peygamberdir. Kendisine <strong>İncil</strong> verilmiştir.</p><p>Havariler: Ona inanan 12 arkadaşı.</p>`,
                    icon: "✝️", activityType: "none", activityTitle: "", activityData: null
                },
                {
                    title: "Mucizeleri",
                    content: `<p>Allah'ın izniyle:</p><ul><li>Beşikteyken konuşması.</li><li>Ölüleri diriltmesi.</li><li>Körü ve alacalı hastayı iyileştirmesi.</li><li>Çamurdan kuşa can vermesi.</li></ul>`,
                    icon: "✨", activityType: "quiz", activityTitle: "Hz. İsa Bilgisi",
                    activityData: [{q:"Hz. İsa'nın annesi kimdir?", options:["Hz. Asiye", "Hz. Meryem"], a:"Hz. Meryem"}, {q:"Hangi kitap verilmiştir?", options:["Tevrat", "İncil"], a:"İncil"}]
                }
            ]
        },
        // 7. NÂS SURESİ
        {
            title: "7. Bir Sure: Nâs Suresi",
            slides: [
                {
                    title: "Tanıtım ve Okunuş",
                    content: `<p>Kur'an'ın son (114.) suresidir. "Nâs" insanlar demektir. Felak suresi ile birlikte "Muavvizeteyn" (İki koruyucu) denir.</p>
                    <div class="verse-box"><span class="arabic-text">قُلْ اَعُوذُ بِرَبِّ النَّاسِۙ</span>1. Kul eûzu birabbinnâs (De ki: Sığınırım insanların Rabbine)</div>
                    <div class="verse-box"><span class="arabic-text">مَلِكِ النَّاسِۙ</span>2. Melikinnâs (İnsanların Melik'ine/Hükümdarına)</div>
                    <div class="verse-box"><span class="arabic-text">اِلٰهِ النَّاسِۙ</span>3. İlâhinnâs (İnsanların İlahına)</div>`,
                    icon: "🤲", activityType: "ordering", activityTitle: "İlk 3 Ayeti Sırala",
                    activityData: ["Kul eûzu birabbinnâs", "Melikinnâs", "İlâhinnâs"]
                },
                {
                    title: "Devamı ve Anlamı",
                    content: `<div class="verse-box"><span class="arabic-text">مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِۙ</span>4. Min şerril vesvâsil ḫannâs (Sinsi vesvesecinin şerrinden)</div>
                    <div class="verse-box"><span class="arabic-text">اَلَّذ۪ي يُوَسْوِسُ ف۪ي صُدُورِ النَّاسِۙ</span>5. Ellezî yuvesvisu fî sudûrinnâs (O ki insanların göğüslerine vesvese verir)</div>
                    <div class="verse-box"><span class="arabic-text">مِنَ الْجِنَّةِ وَالنَّاسِ</span>6. Minel cinneti vennâs (Gerek cinlerden gerek insanlardan)</div>`,
                    icon: "🛡️", activityType: "matching", activityTitle: "Anlam Eşleştirme",
                    activityData: [{term:"Nâs", def:"İnsanlar"}, {term:"Vesvese", def:"Kötü fısıltı"}, {term:"Rab/Melik/İlah", def:"Allah'ın sıfatları"}, {term:"Hannas", def:"Sinsi vesveseci"}]
                }
            ]
        }
    ];

    /* --- DURUM YÖNETİMİ --- */
    let currentUnitIdx = 0;
    let currentSlideIdx = 0;
    let currentData = null;
    let selectedItem = null;
    let anagramIndex = 0;
    let currentAnagramState = { word:"", pos:0 };

    /* --- GÖRÜNÜM KONTROLÜ --- */
    function init() {
        fitScreen();
    }

    // Expose functions to window so HTML onClick works with scoped functions
    window.appFunctions = {
        zoomIn: () => { manualZoom += 0.1; fitScreen(); },
        zoomOut: () => { if(currentScale > 0.3) { manualZoom -= 0.1; fitScreen(); } },
        toggleFullScreen: () => {
            if (!document.fullscreenElement) { document.documentElement.requestFullscreen(); }
            else { if (document.exitFullscreen) { document.exitFullscreen(); } }
        },
        selectUnit: (index) => {
            currentUnitIdx = index;
            currentSlideIdx = 0;
            document.getElementById('menu-screen').style.display = 'none';
            document.getElementById('unit-screen').style.display = 'flex';
            document.getElementById('unit-title').textContent = units[index].title;
            renderSlide();
        },
        returnToMenu: () => {
            document.getElementById('unit-screen').style.display = 'none';
            document.getElementById('menu-screen').style.display = 'flex';
        },
        nextSlide: () => { if(currentSlideIdx < units[currentUnitIdx].slides.length-1) { currentSlideIdx++; renderSlide(); } },
        prevSlide: () => { if(currentSlideIdx > 0) { currentSlideIdx--; renderSlide(); } },
        openActivity: () => {
            const slide = units[currentUnitIdx].slides[currentSlideIdx];
            const board = document.getElementById('game-board');
            document.getElementById('activity-overlay').style.display = 'flex';
            document.getElementById('activity-title').textContent = slide.activityTitle;
            document.getElementById('feedback').textContent = "";
            board.innerHTML = "";
            currentData = slide.activityData;

            if(slide.activityType === 'quiz') loadQuiz(board, currentData);
            else if(slide.activityType === 'matching') loadMatching(board, currentData);
            else if(slide.activityType === 'ordering') loadOrdering(board, currentData);
            else if(slide.activityType === 'anagram') { anagramIndex=0; loadAnagram(board, currentData); }
        },
        closeActivity: () => { document.getElementById('activity-overlay').style.display = 'none'; }
    };

    function renderSlide() {
        const slide = units[currentUnitIdx].slides[currentSlideIdx];
        const container = document.getElementById('slide-container');
        document.getElementById('current-page').innerText = currentSlideIdx + 1;
        document.getElementById('prev-btn').disabled = currentSlideIdx === 0;
        document.getElementById('next-btn').disabled = currentSlideIdx === units[currentUnitIdx].slides.length - 1;

        let btnHtml = slide.activityType !== "none"
            ? `<button class="activity-btn" onclick="window.appFunctions.openActivity()">🎮 ETKİNLİK BAŞLAT</button>` 
            : ``;

        container.innerHTML = `
            <div class="text-panel"><h2>${slide.title}</h2>${slide.content}</div>
            <div class="visual-panel"><div class="visual-icon">${slide.icon}</div>${btnHtml}</div>
        `;
    }

    /* --- ETKİNLİK MOTORU --- */

    // 1. QUIZ
    function loadQuiz(board, data) {
        const show = (idx) => {
            if(idx >= data.length) { board.innerHTML="<h2 class='success'>Tamamladın! 🎉</h2>"; return; }
            let q = data[idx];
            board.innerHTML = `<h3 style="font-size:1.8rem; text-align:center;">${q.q}</h3><div id="opts" style="width:100%; display:flex; flex-direction:column; align-items:center;"></div>`;
            q.options.forEach(opt => {
                let btn = document.createElement("div"); btn.className = "quiz-option"; btn.textContent = opt;
                btn.onclick = function() { 
                    if(opt === q.a) { this.style.background="#059669"; setTimeout(()=>show(idx+1), 600); }
                    else { this.style.background="#dc2626"; }
                };
                document.getElementById('opts').appendChild(btn);
            });
        };
        show(0);
    }

    // 2. EŞLEŞTİRME (YATAY DÜZEN)
    function loadMatching(board, data) {
        board.innerHTML = `<div class="match-container"><div class="match-col" id="left"></div><div class="match-col" id="right"></div></div>`;
        let leftCol = document.getElementById('left');
        let rightCol = document.getElementById('right');
        let rightItems = [...data].sort(() => Math.random() - 0.5);

        data.forEach(item => {
            let btn = document.createElement('div'); btn.className = 'match-item'; 
            btn.textContent = item.term; btn.dataset.pair = item.def;
            btn.onclick = () => selectLeft(btn); leftCol.appendChild(btn);
        });

        rightItems.forEach(item => {
            let btn = document.createElement('div'); btn.className = 'match-item'; 
            btn.textContent = item.def;
            btn.onclick = () => checkMatch(btn); rightCol.appendChild(btn);
        });
    }

    function selectLeft(elem) {
        if(elem.classList.contains('matched')) return;
        // Fix: Use correct ID selector '#left' instead of '#col-left'
        document.querySelectorAll('#left .match-item').forEach(e => e.classList.remove('selected'));
        elem.classList.add('selected'); selectedItem = elem;
    }

    function checkMatch(elem) {
        if(!selectedItem || elem.classList.contains('matched')) return;
        const feedback = document.getElementById('feedback');
        if(selectedItem.dataset.pair === elem.textContent) {
            elem.classList.add('matched'); selectedItem.classList.add('matched'); selectedItem.classList.remove('selected'); selectedItem = null;
            feedback.innerHTML = "<span class='success'>Doğru!</span>";
            // Fix: Use correct ID selector '#left'
            if(document.querySelectorAll('#left .match-item:not(.matched)').length === 0) feedback.innerHTML = "<span class='success'>Tebrikler!</span>";
        } else {
            elem.classList.add('wrong'); setTimeout(() => elem.classList.remove('wrong'), 500);
            feedback.innerHTML = "<span class='error'>Yanlış!</span>";
        }
    }

    // 3. SIRALAMA
    function loadOrdering(board, data) {
        board.innerHTML = `<p style="text-align:center; font-size:1.5rem;">Sırasıyla seç:</p><div id="sort-area" class="sort-container"></div>`;
        let area = document.getElementById('sort-area');
        let shuffled = [...data].sort(()=>Math.random()-0.5);
        let step = 0;

        shuffled.forEach(txt => {
            let div = document.createElement('div'); div.className = 'sort-item'; div.textContent = txt;
            div.onclick = function() {
                if(txt === data[step]) {
                    this.style.background = '#059669'; this.style.pointerEvents='none'; step++;
                    if(step === data.length) document.getElementById('feedback').innerHTML="<span class='success'>Tebrikler!</span>";
                } else {
                    this.style.background = '#dc2626'; setTimeout(()=>this.style.background='#312e81', 500);
                }
            };
            area.appendChild(div);
        });
    }

    // 4. ANAGRAM
    function loadAnagram(board, data) {
        if(anagramIndex >= data.length) { board.innerHTML="<h2 class='success'>Bitti! 🎉</h2>"; return; }
        let item = data[anagramIndex];
        currentAnagramState = { word: item.answer, pos: 0 };
        board.innerHTML = `<div class="anagram-container"><div style="margin-bottom:20px; color:#93c5fd; font-size:1.5rem;">İpucu: ${item.hint}</div><div id="slots" class="anagram-slots"></div><div id="pool" class="letter-pool"></div></div>`;

        for(let i=0; i<item.answer.length; i++) {
            let s = document.createElement('div'); s.className='anagram-slot'; s.id=`s-${i}`; document.getElementById('slots').appendChild(s);
        }
        item.scrambled.split('').forEach(char => {
            let btn = document.createElement('button'); btn.className='letter-btn'; btn.textContent=char;
            btn.onclick = function() {
                if(char === currentAnagramState.word[currentAnagramState.pos]) {
                    document.getElementById(`s-${currentAnagramState.pos}`).textContent = char;
                    this.classList.add('correct'); currentAnagramState.pos++;
                    if(currentAnagramState.pos >= item.answer.length) { anagramIndex++; setTimeout(()=>loadAnagram(board, data), 1000); }
                } else {
                    this.classList.add('wrong'); setTimeout(()=>this.classList.remove('wrong'), 400);
                }
            };
            document.getElementById('pool').appendChild(btn);
        });
    }

    // Event listeners attached to window for scope safety
    window.addEventListener('resize', fitScreen);
    window.addEventListener('load', fitScreen);

    // Başlat
    init();
}
</script>
</body>
</html>"
}

